import * as T from './three.module.js';
import { RoundedBoxGeometry } from './rounded-box.js';
import { RoomEnvironment } from './room-environment.js';
export { T };
export const clamp=T.MathUtils.clamp;
export const smooth=(v,a=0,b=1)=>T.MathUtils.smoothstep(v,a,b);
export const mix=T.MathUtils.lerp;
const textures=new T.TextureLoader();
export const earthMap=textures.load('./assets/earth.jpg');earthMap.colorSpace=T.SRGBColorSpace;earthMap.anisotropy=8;
function material(color,roughness=.6,metalness=0){return new T.MeshStandardMaterial({color,roughness,metalness})}
export function rounded(w,h,d,r,mat){return new T.Mesh(new RoundedBoxGeometry(w,h,d,3,Math.min(r,d/2)),mat)}
function shape(w,h,r){const p=new T.Shape(),x=-w/2,y=-h/2;p.moveTo(x+r,y);p.lineTo(x+w-r,y);p.quadraticCurveTo(x+w,y,x+w,y+r);p.lineTo(x+w,y+h-r);p.quadraticCurveTo(x+w,y+h,x+w-r,y+h);p.lineTo(x+r,y+h);p.quadraticCurveTo(x,y+h,x,y+h-r);p.lineTo(x,y+r);p.quadraticCurveTo(x,y,x+r,y);return p}
export function face(w,h,r,mat){const g=new T.ShapeGeometry(shape(w,h,r),10);const p=g.attributes.position,u=g.attributes.uv;for(let i=0;i<p.count;i++)u.setXY(i,p.getX(i)/w+.5,p.getY(i)/h+.5);return new T.Mesh(g,mat)}
export function createStage(mount,{dark=false,fov=37}={}){
 let renderer;try{renderer=new T.WebGLRenderer({alpha:true,antialias:true,powerPreference:'high-performance'})}catch{return null}
 renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<760?1.35:1.75));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=dark?1.2:1.05;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;mount.append(renderer.domElement);
 const scene=new T.Scene();const pmrem=new T.PMREMGenerator(renderer);const room=new RoomEnvironment();const environment=pmrem.fromScene(room,.04);scene.environment=environment.texture;scene.environmentIntensity=dark?.6:.85;room.dispose();pmrem.dispose();
 scene.add(new T.HemisphereLight(0xf4f9ff,0xa4b1b9,dark?1.2:1.7));const key=new T.DirectionalLight(0xfff5e5,dark?3.1:3.6);key.position.set(-3,6,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-6;key.shadow.camera.right=6;key.shadow.camera.top=5;key.shadow.camera.bottom=-5;key.shadow.normalBias=.035;key.shadow.bias=-.0002;key.shadow.radius=5;scene.add(key);const fill=new T.DirectionalLight(0xb5e4ff,dark?1.8:.9);fill.position.set(5,1,-4);scene.add(fill);
 const camera=new T.PerspectiveCamera(fov,1,.1,60);camera.position.set(0,3.5,9);const ground=new T.Mesh(new T.PlaneGeometry(24,24),new T.ShadowMaterial({opacity:dark?.16:.1}));ground.rotation.x=-Math.PI/2;ground.position.y=-1.5;ground.receiveShadow=true;scene.add(ground);
 let inView=true,active=true,draw=()=>{},last=performance.now();const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 function frame(now){const dt=Math.min((now-last)/1000,.04);last=now;draw(dt,now/1000,reduced.matches);renderer.render(scene,camera)}
 function visibility(){renderer.setAnimationLoop(inView&&active&&!document.hidden?frame:null);last=performance.now()}
 new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;visibility()},{rootMargin:'80px'}).observe(mount);document.addEventListener('visibilitychange',visibility);
 function resize(){const b=mount.getBoundingClientRect();if(!b.width||!b.height)return;renderer.setSize(b.width,b.height,false);camera.aspect=b.width/b.height;camera.updateProjectionMatrix()}
 new ResizeObserver(resize).observe(mount);resize();
 return {renderer,scene,camera,ground,setDraw(fn){draw=fn;visibility()},pause(value){active=!value;visibility()},render(){frame(performance.now())},damp(a,b,dt,rate=5){return mix(a,b,1-Math.exp(-rate*dt))}};
}
function canvasTexture(draw,w=768,h=1024){const c=document.createElement('canvas');c.width=w;c.height=h;draw(c.getContext('2d'),w,h);const tx=new T.CanvasTexture(c);tx.colorSpace=T.SRGBColorSpace;tx.anisotropy=8;return tx}
function paperTexture(side){return canvasTexture((c,w,h)=>{c.fillStyle='#f9f5ed';c.fillRect(0,0,w,h);let shade=c.createLinearGradient(0,0,w,0);shade.addColorStop(side<0?0:1,'#ffffff00');shade.addColorStop(side<0?1:0,'#796e562d');c.fillStyle=shade;c.fillRect(0,0,w,h);c.fillStyle='#688591';c.font='bold 18px Arial';c.fillText('SEMANOOR  /  KNOWLEDGE IN MOTION',62,82);c.fillStyle='#173d53';c.font='52px Georgia';c.fillText(side<0?'Every discovery':'A world beyond',62,180);c.fillText(side<0?'starts here.':'the page.',62,242);c.fillStyle='#8b9b9c';for(let i=0;i<15;i++){c.fillRect(65,325+i*25,w-140-(i%5===4?160:0),3)}c.strokeStyle='#a6c8cd';c.lineWidth=2;c.beginPath();c.arc(w/2,805,90,0,Math.PI*2);c.stroke();for(let i=0;i<3;i++){c.beginPath();c.ellipse(w/2,805,90,27,i*1.04,0,7);c.stroke()}c.fillStyle='#1e7884';c.beginPath();c.arc(w/2,805,9,0,7);c.fill();c.font='16px Arial';c.fillStyle='#95a5a7';c.fillText(side<0?'01':'02',65,h-48)})}
function pageGeometry(side,base,curl=0){const g=new T.PlaneGeometry(2,2.8,26,12);const p=g.attributes.position,u=g.attributes.uv;for(let i=0;i<p.count;i++){const a=(p.getX(i)+1)/2,b=(p.getY(i)+1.4)/2.8;p.setXYZ(i,side*(.035+a*2),base+.11*Math.sin(a*Math.PI)+curl*Math.sin(a*Math.PI*.85),(.5-b)*2.8);u.setXY(i,side<0?1-a:a,b)}g.computeVertexNormals();return g}
export function createBook(){
 const root=new T.Group(),leaves=[];const coverMat=new T.MeshPhysicalMaterial({color:0x075987,roughness:.47,metalness:.07,clearcoat:.18});const paperMat=material(0xe9e0d1,.9);const bindings=rounded(.16,.24,2.93,.06,coverMat);bindings.position.y=-.09;root.add(bindings);
 for(const side of [-1,1]){const hinge=new T.Group();root.add(hinge);leaves.push(hinge);let cover=rounded(2.15,.1,2.98,.04,coverMat);cover.position.set(side*1.045,-.19,0);cover.castShadow=true;hinge.add(cover);let block=rounded(1.98,.17,2.8,.022,paperMat);block.position.set(side*1.025,-.05,0);block.castShadow=true;hinge.add(block);for(let i=0;i<7;i++){const sheet=new T.Mesh(pageGeometry(side,.039+i*.004,i*.009),new T.MeshStandardMaterial({color:i===6?0xffffff:0xf4eee1,roughness:.87,side:T.DoubleSide,map:i===6?paperTexture(side):null}));sheet.receiveShadow=true;sheet.castShadow=i===6;hinge.add(sheet)}
 const edge=new T.LineSegments(new T.EdgesGeometry(new T.BoxGeometry(1.98,.14,2.79),30),new T.LineBasicMaterial({color:0xc8bcaa,transparent:true,opacity:.2}));edge.position.copy(block.position);hinge.add(edge)}
 const ribbon=new T.Mesh(new T.PlaneGeometry(.07,1.55),new T.MeshStandardMaterial({color:0x347a61,side:T.DoubleSide,roughness:.8}));ribbon.rotation.x=-Math.PI/2;ribbon.position.set(.09,.084,1.14);root.add(ribbon);
 const turn=new T.Group();root.add(turn);const sheet=new T.Mesh(pageGeometry(1,.094,.17),new T.MeshStandardMaterial({map:paperTexture(1),side:T.DoubleSide,roughness:.8}));sheet.castShadow=true;turn.add(sheet);
 return {root,leaves,turn,open(amount=1,flip=0){const angle=mix(.98,.035,amount);leaves[0].rotation.z=-angle;leaves[1].rotation.z=angle;turn.rotation.z=angle+flip*Math.PI;turn.visible=flip>.01&&flip<.99}};
}
export function createGlobe(radius=.86){const root=new T.Group();const earth=new T.Mesh(new T.SphereGeometry(radius,64,40),new T.MeshPhysicalMaterial({map:earthMap,roughness:.64,metalness:0,clearcoat:.15}));earth.castShadow=true;earth.rotation.y=-2.35;root.add(earth);const air=new T.Mesh(new T.SphereGeometry(radius*1.028,40,28),new T.ShaderMaterial({transparent:true,depthWrite:false,uniforms:{tint:{value:new T.Color(0x80cbef)}},vertexShader:'varying vec3 n; varying vec3 v; void main(){vec4 p=modelViewMatrix*vec4(position,1.0);n=normalize(normalMatrix*normal);v=-p.xyz;gl_Position=projectionMatrix*p;}',fragmentShader:'uniform vec3 tint;varying vec3 n;varying vec3 v;void main(){float f=pow(1.0-max(dot(normalize(n),normalize(v)),0.0),3.3);gl_FragColor=vec4(tint,f*.38);}'}));root.add(air);return {root,earth}}
export function createCard(title,kind='heritage',w=1.5,h=1.04){
 const root=new T.Group();let back=rounded(w+.08,h+.08,.065,.025,new T.MeshPhysicalMaterial({color:0xc1d2d9,metalness:.55,roughness:.23}));root.add(back);let c=document.createElement('canvas');c.width=768;c.height=512;const ctx=c.getContext('2d');function draw(img){ctx.fillStyle='#eef4f4';ctx.fillRect(0,0,768,512);if(img){let ratio=Math.max(720/img.width,338/img.height),cw=720/ratio,ch=338/ratio;ctx.drawImage(img,(img.width-cw)*.67,(img.height-ch)*.5,cw,ch,24,24,720,338)}else{ctx.fillStyle='#123f5d';ctx.fillRect(24,24,720,338);ctx.strokeStyle='#80bed5';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(385,190,150,52,i*.8,0,7);ctx.stroke()}ctx.fillStyle='#d4d6c2';ctx.beginPath();ctx.arc(385,190,33,0,7);ctx.fill()}ctx.fillStyle='#155075';ctx.font='bold 24px Arial';ctx.fillText(kind==='heritage'?'SAUDI HERITAGE':'INTERACTIVE SCIENCE',30,414);ctx.fillStyle='#587485';ctx.font='31px Georgia';ctx.fillText(title,30,465);if(tx)tx.needsUpdate=true}let tx;draw();tx=new T.CanvasTexture(c);tx.colorSpace=T.SRGBColorSpace;tx.anisotropy=8;if(kind==='heritage'){let image=new Image();image.onload=()=>draw(image);image.src='./saudi-landscape.webp'}let front=face(w,h,.025,new T.MeshBasicMaterial({map:tx}));front.position.z=.037;root.add(front);return root;
}
export function createTablet(){const root=new T.Group();let shell=rounded(2.62,3.46,.14,.065,new T.MeshPhysicalMaterial({color:0x8a9ca9,roughness:.25,metalness:.86}));shell.castShadow=true;root.add(shell);const bezel=face(2.54,3.38,.15,material(0x101f2a,.28,.12));bezel.position.z=.076;root.add(bezel);let tx=canvasTexture((c,w,h)=>{c.fillStyle='#f2f6f5';c.fillRect(0,0,w,h);c.fillStyle='#08436a';c.fillRect(0,0,w,105);c.fillStyle='#fff';c.font='bold 24px Arial';c.fillText('SEMANOOR',42,62);c.fillStyle='#44687b';c.font='19px Arial';c.fillText('YOUR WORLD OF LEARNING',44,158);c.font='52px Georgia';c.fillStyle='#153f57';c.fillText('Where will curiosity',42,235);c.fillText('take you today?',42,295);c.fillStyle='#0d5c86';c.fillRect(40,342,w-80,320);c.strokeStyle='#98cedc';for(let i=0;i<3;i++){c.beginPath();c.ellipse(w/2,500,155,55,i*.7,0,7);c.stroke()}c.fillStyle='#d4e5da';c.beginPath();c.arc(w/2,500,41,0,7);c.fill();c.fillStyle='#184761';c.font='bold 25px Arial';c.fillText('Continue your discovery',43,727);for(let i=0;i<3;i++){c.fillStyle='#dbe7e9';c.fillRect(43,763+i*63,65,45);c.fillStyle='#74919f';c.fillRect(130,775+i*63,350-i*45,5);c.fillStyle='#b4c9d1';c.fillRect(130,793+i*63,220,4)}c.fillStyle='#0f74a5';c.fillRect(44,969,440,5)});let screen=face(2.35,3.12,.075,new T.MeshBasicMaterial({map:tx}));screen.position.z=.08;root.add(screen);let lens=new T.Mesh(new T.SphereGeometry(.018,12,8),material(0x0d101c,.1,.2));lens.scale.z=.2;lens.position.set(0,1.66,.08);root.add(lens);let button=rounded(.024,.31,.045,.01,material(0x8493a1,.3,.8));button.position.set(1.323,.8,0);root.add(button);return root}
export function createCourtyard(){const root=new T.Group(),sand=material(0xc4a17c,.92),trim=material(0xe4ccaa,.83),dark=material(0x5e5449,.98);const base=new T.Mesh(new T.CylinderGeometry(1.62,1.68,.12,64),material(0xcdb797,.93));base.position.y=-.055;base.receiveShadow=true;base.castShadow=true;root.add(base);const wallShape=new T.Shape();wallShape.moveTo(-1.1,0);wallShape.lineTo(1.1,0);wallShape.lineTo(1.1,1.42);wallShape.lineTo(-1.1,1.42);wallShape.closePath();const gate=new T.Path();gate.moveTo(-.33,0);gate.lineTo(-.33,.64);gate.absarc(0,.64,.33,Math.PI,0,true);gate.lineTo(.33,0);gate.closePath();wallShape.holes.push(gate);const wall=new T.Mesh(new T.ExtrudeGeometry(wallShape,{depth:.27,bevelEnabled:true,bevelSize:.017,bevelThickness:.017,bevelSegments:2,steps:1,curveSegments:20}),sand);wall.position.z=-.12;wall.castShadow=true;wall.receiveShadow=true;root.add(wall);for(let side of [-1,1]){const tower=rounded(.47,1.78,.56,.04,sand);tower.position.set(side*1.12,.89,0);tower.castShadow=true;root.add(tower);for(let y=0;y<3;y++){let inset=face(.095,.17,0,dark);inset.position.set(side*1.12,.55+y*.32,.288);root.add(inset)}for(let i=0;i<3;i++){const tooth=rounded(.13,.16,.6,.022,trim);tooth.position.set(side*1.12+(i-1)*.17,1.82,0);tooth.castShadow=true;root.add(tooth)}}for(let i=0;i<10;i++){const tooth=rounded(.13,.12,.32,.015,trim);tooth.position.set(-.9+i*.2,1.46,0);root.add(tooth)}for(let i=0;i<4;i++){const step=rounded(.68+i*.15,.05,.16,.015,trim);step.position.set(0,.1-i*.018,.31+i*.15);step.receiveShadow=true;root.add(step)}const path=face(.12,1.0,.02,material(0x578a7a,.7));path.rotation.x=-Math.PI/2;path.position.set(0,.014,.96);root.add(path);return root}
